def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    top = min(r for r, c, color in cells)
    tops = {}
    for r, c, color in cells:
        tops[color] = min(tops.get(color, r), r)
    out = [[0] * w for _ in range(h)]
    for r, c, color in cells:
        nr = r + top - tops[color]
        out[nr][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    anchor_top = min(r for r, c, color in cells if color == 8)
    tops = {}
    for r, c, color in cells:
        tops[color] = min(tops.get(color, r), r)
    out = [[0] * w for _ in range(h)]
    for r, c, color in cells:
        nr = r + anchor_top - tops[color]
        out[nr][c] = color
    return out
